"""Orthographic art review using the exact ellipsoids generated by PetGeometry.
This is a geometry preview, not a claim of Roblox Studio rendering verification.
Usage: python tools/render_pet_preview.py input.json output.png
"""
import json
import math
import sys
import numpy as np
from PIL import Image, ImageDraw, ImageFont


def rotation(degrees):
    x, y, z = np.radians(degrees)
    cx, sx, cy, sy, cz, sz = np.cos(x), np.sin(x), np.cos(y), np.sin(y), np.cos(z), np.sin(z)
    return np.array([[1, 0, 0], [0, cx, -sx], [0, sx, cx]]) @ np.array([[cy, 0, sy], [0, 1, 0], [-sy, 0, cy]]) @ np.array([[cz, -sz, 0], [sz, cz, 0], [0, 0, 1]])


def render(pet, width=320, height=340):
    view = np.array([3.0, 2.2, -9.0]); view /= np.linalg.norm(view)
    right = np.cross(view, [0, 1, 0]); right /= np.linalg.norm(right)
    up = np.cross(right, view)
    u, v = np.meshgrid(np.linspace(-3.4, 3.4, width), np.linspace(3.4, -3.4, height))
    origin = np.array([0, 2.1, 0]) + u[..., None] * right + v[..., None] * up + 20 * view
    direction = -view
    depth = np.full((height, width), np.inf)
    background = np.array([241, 239, 231], dtype=float)
    image = np.broadcast_to(background, (height, width, 3)).copy()
    shadow = np.exp(-((u / 1.35) ** 2 + ((v + 2.05) / 0.27) ** 2)) * 0.14
    image *= 1 - shadow[..., None]
    light = np.array([-3, 6, -8], dtype=float); light /= np.linalg.norm(light)
    for part in pet["Parts"]:
        scale = pet["Scale"]
        center, radii = np.array(part["Position"]) * scale, np.array(part["Size"]) * scale / 2
        matrix = rotation(part["Rotation"])
        local_origin = (origin - center) @ matrix / radii
        local_direction = direction @ matrix / radii
        a = np.dot(local_direction, local_direction)
        b = 2 * np.sum(local_origin * local_direction, axis=2)
        c = np.sum(local_origin * local_origin, axis=2) - 1
        discriminant = b*b - 4*a*c
        distance = (-b - np.sqrt(np.maximum(discriminant, 0))) / (2*a)
        mask = (discriminant >= 0) & (distance > 0) & (distance < depth)
        if not np.any(mask):
            continue
        hit = (origin[mask] + distance[mask, None] * direction - center) @ matrix
        normal = (hit / (radii*radii)) @ matrix.T
        normal /= np.linalg.norm(normal, axis=1)[:, None]
        diffuse = np.maximum(normal @ light, 0)
        shade = 0.50 + 0.50 * diffuse
        color = np.array(part["Color"])[None, :] * shade[:, None]
        image[mask] = np.clip(color, 0, 255)
        depth[mask] = distance[mask]
    return Image.fromarray(image.astype(np.uint8))


def main():
    with open(sys.argv[1], encoding="utf-8-sig") as handle:
        pets = json.load(handle)
    columns = 4
    rows = math.ceil(len(pets) / columns)
    output = Image.new("RGB", (columns * 320, 75 + rows * 400), "#f1efe7")
    draw = ImageDraw.Draw(output)
    try:
        title_font = ImageFont.truetype("C:/Windows/Fonts/segoeuib.ttf", 24)
        font = ImageFont.truetype("C:/Windows/Fonts/segoeui.ttf", 16)
    except OSError:
        title_font = font = ImageFont.load_default()
    draw.text((24, 14), "PET RESCUE / ORIGINAL PLUSH PETS", font=title_font, fill="#324b46")
    draw.text((24, 46), "Exact geometry preview • Roblox lighting and gameplay require Studio verification", font=font, fill="#677d74")
    for index, pet in enumerate(pets):
        x, y = index % columns * 320, 75 + index // columns * 400
        output.paste(render(pet), (x, y))
        draw.text((x + 20, y + 337), pet["Title"], font=title_font, fill="#324b46")
        draw.text((x + 20, y + 370), pet["Subtitle"], font=font, fill="#677d74")
    output.save(sys.argv[2])


if __name__ == "__main__":
    main()
